return [{
  json: {
    mensaje: '🌙 Cafetería Cerrada. Nuestro horario es de Lunes a Viernes, 8am a 5pm. ¡Te esperamos mañana!',
    reply_markup: { inline_keyboard: [[{ text: '🏠 Menú Principal', callback_data: 'main_menu' }]] },
    session_updates: { estado_fsm: 'IDLE', carrito_json: '[]', contexto_json: '{}' }
  }
}];

const inputData = $('Execute Workflow Trigger').first().json;
const menuItems = $('Read Menu').all().map(i => i.json);
let cart = [];
let contexto = {};
try { cart = JSON.parse(inputData.carrito_json || '[]'); } catch(e) {}
try { contexto = JSON.parse(inputData.contexto_json || '{}'); } catch(e) {}

const TAX_RATE = 0.12;
let subtotal = 0;
let errors = [];

for (const item of cart) {
  const menuItem = menuItems.find(m => m.id_producto === item.id);
  if (!menuItem) {
    errors.push(item.nombre + ' ya no está disponible');
    continue;
  }
  const stock = parseInt(menuItem.stock);
  if (stock < item.qty) {
    errors.push(item.nombre + ': solo quedan ' + stock + ' unidades');
    continue;
  }
  subtotal += item.qty * parseFloat(menuItem.precio);
}

const tipo_entrega = contexto.tipo_entrega || 'Local';
const metodo_pago = contexto.metodo_pago || 'Efectivo';
const costo_envio = (tipo_entrega === 'Delivery') ? 2.00 : 0.00;

const iva = Math.round((subtotal + costo_envio) * TAX_RATE * 100) / 100;
const total = Math.round((subtotal + costo_envio + iva) * 100) / 100;

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const randomNum = Math.floor(1000 + Math.random() * 9000);
const orderId = 'ORD-' + dateStr + '-' + randomNum;
const detalles = cart.map(i => i.nombre + ' x' + i.qty).join(', ');

return [{ json: {
  valid: errors.length === 0,
  errors: errors,
  id_pedido: orderId, subtotal: subtotal, iva: iva, total_pago: total, detalles_pedido: detalles, estado: 'RECIBIDO',

  telegram_id: inputData.telegram_id,
  chat_id: inputData.chat_id,
  first_name: inputData.first_name || 'Usuario',
  fecha: now.toISOString().split('T')[0],
  hora: now.toTimeString().split(' ')[0],
  carrito_json: inputData.carrito_json,
  tipo_entrega: tipo_entrega,
  metodo_pago: metodo_pago
}}];

const calc = $('Validate & Calculate').first().json;

const text = '🛎 *Nuevo Pedido Recibido*\n\n📦 Orden: #' + calc.id_pedido + '\n👤 ' + calc.first_name + '\n📋 ' + calc.detalles_pedido + '\n🛵 Tipo: ' + calc.tipo_entrega + '\n💵 Total: $' + calc.total_pago.toFixed(2);

const keyboard = {
  inline_keyboard: [
    [
      { text: '🍳 Preparar', callback_data: 'admin_prep_' + calc.id_pedido },
      { text: '❌ Rechazar', callback_data: 'admin_reject_' + calc.id_pedido }
    ]
  ]
};

return [{ json: {
  chat_id: -5174866298,
  text: text,
  parse_mode: 'Markdown',
  reply_markup: keyboard
}}];

const menuItems = $('Read Menu').all().map(i => i.json);
const calc = $('Validate & Calculate').first().json;
let cart = [];
try { cart = JSON.parse(calc.carrito_json || '[]'); } catch(e) {}

const results = [];
for (const cartItem of cart) {
  const menuItem = menuItems.find(m => m.id_producto === cartItem.id);
  if (menuItem) {
    results.push({
      json: {
        id_producto: cartItem.id,
        stock: parseInt(menuItem.stock) - cartItem.qty
      }
    });
  }
}
return results.length > 0 ? results : [{ json: { id_producto: 'none', stock: 0 } }];

const calc = $('Validate & Calculate').first().json;
const allOrders = $('Read PEDIDOS').all().map(i => i.json);

let activeQueue = 0;
allOrders.forEach(o => {
  if (o.estado === 'RECIBIDO' || o.estado === 'EN_PREPARACION') {
    activeQueue++;
  }
});

let etaMsg = '15 minutos';
if (activeQueue > 3) {
  etaMsg = (15 + (activeQueue * 5)) + ' minutos (hay alta demanda con ' + activeQueue + ' pedidos en cola)';
} else if (activeQueue > 0) {
  etaMsg = (15 + (activeQueue * 5)) + ' minutos';
}

let msg = '✅ *¡Pedido confirmado!*\n\n📦 Orden: #' + calc.id_pedido + '\n💰 Subtotal: $' + calc.subtotal.toFixed(2);
if (calc.tipo_entrega === 'Delivery') msg += '\n🛵 Envío: $2.00';
msg += '\n📊 IVA (12%): $' + calc.iva.toFixed(2) + '\n💵 Total: $' + calc.total_pago.toFixed(2);
msg += '\n\n📍 Entrega: ' + calc.tipo_entrega + '\n💳 Pago: ' + calc.metodo_pago;
msg += '\n\n⏳ *Tiempo estimado de entrega:* ' + etaMsg;
msg += '\n\nTe notificaremos cuando esté en preparación. 🍳';

return [{
  json: {
    mensaje: msg,
    reply_markup: { inline_keyboard: [[{ text: '🏠 Menú Principal', callback_data: 'main_menu' }]] },
    session_updates: { estado_fsm: 'IDLE', carrito_json: '[]', contexto_json: '{}' }
  }
}];

const calc = $('Validate & Calculate').first().json;
const errorList = calc.errors.join('\n• ');
return [{
  json: {
    mensaje: '⚠️ *No se pudo procesar tu pedido*\n\n• ' + errorList + '\n\nPor favor, ajusta tu carrito e intenta de nuevo.',
    reply_markup: { inline_keyboard: [
      [{ text: '🛒 Ver Carrito', callback_data: 'view_cart' }],
      [{ text: '🏠 Menú Principal', callback_data: 'main_menu' }]
    ]},
    session_updates: { estado_fsm: 'CARRITO', carrito_json: calc.carrito_json, contexto_json: '{}' }
  }
}];
